// CSD_RATIONALE_BEGIN
// Root cause of all 144 mode_A failures: the `<<` delimiter is NEVER generated
// by the LM (visible `<<` count = 0/300), because the 5-step preamble allows
// the model to emit SQL tokens ("SELECT col FROM table") before "<<" appears.
// Phase 2 then force-injects "<<" via OpenConstrainedSpan, which is an invisible
// (structural) token. The evaluator cannot find a matched visible <<...>> pair,
// falls back to text_fallback, and extracts the wrong SQL from the unconstrained
// preamble content.
//
// Evidence from rollouts:
//   Preamble tokens: "SELECT", "name", ",", "age"  (4 tokens before << is forced)
//   Generated:  "SELECT name, age<<SELECT age, hometown FROM teacher>>"
//   TextFallback extracts: "SELECT name, age"  (WRONG - from preamble)
//   Constrained span has: "SELECT age, hometown FROM teacher"  (CORRECT)
//
// Fix: Increase preamble to 10 steps AND add guidance that explicitly instructs
// the model to emit "<<" BEFORE any SQL keyword. If the LM naturally emits "<<"
// (detected via RenderedEndsWith), the span becomes visible, enabling
// final_answer_span extraction instead of text_fallback. This should raise
// accuracy from 52-53% toward the correct-SQL fraction of constrained output.
//
// Secondary fix: guidance targeting the dominant semantic error (extra-column
// selection). "What is X and Y?" → model sometimes emits name, X, Y instead of
// just X, Y. One concise instruction ("Select ONLY the columns the question asks
// for") keeps guidance short to avoid the attempt-73 regression (4 rules → -5pp).
//
// Budget: 10 (preamble) + 1 (force <<) + 400 (constrained SQL) = 411 << 900.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Loop guard includes !insideConstrainedOut, so the
//   implication is vacuously true on every iteration while outside a span.
//   The only true-flip is via RenderedEndsWith(generated, "<<"), at which
//   point we set currentConstrainedOut := []. IsValidPrefix([]) holds by
//   the method precondition `parser.IsValidPrefix([])`. EOS break leaves
//   insideConstrainedOut unchanged (still false, implication vacuous).
//
// Phase 2 OpenConstrainedSpan: Executes only when !insideConstrainedOut.
//   Postcondition sets currentConstrainedOut := [], insideConstrainedOut := true.
//   IsValidPrefix([]) holds by the method precondition. Invariant restored.
//
// Phase 3+4 CloseSpanWithinBudget: Its postcondition directly guarantees both
//   (!insideConstrainedOut ==> currentConstrainedOut == []) and
//   (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)).
//   Both the closed-span path and the still-open path are covered.
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep costs 1 step and appends at most 1 token (0 on
//   EOS path via break, 1 on non-EOS path). The RenderedEndsWith branch only
//   updates span state, not generated length. Each iteration: steps += 1,
//   |generated| grows by at most 1. Preserved invariant per iteration.
//
// Phase 2: OpenConstrainedSpan costs 1 step and appends exactly 1 "<<" token.
//   steps += 1, |generated| += 1. Ratio preserved (1:1).
//
// Phase 3+4: closeBudget = min(remaining, 400) <= maxSteps - steps.
//   CloseSpanWithinBudget postcondition: |cg| <= |generated| + closeBudget.
//   We set steps := steps + closeBudget (steps becomes steps_pre + closeBudget).
//   So |cg| <= |generatedPrefix| + steps_pre + closeBudget = |generatedPrefix| + new_steps.
//   Tokens consumed by dead-end avoidance or EOS that are not appended visibly
//   still count against closeBudget, so visible growth is bounded by closeBudget.
//   cost = steps_pre + closeBudget <= maxSteps: closeBudget <= maxSteps - steps_pre ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Format: SQL: <<SELECT ... FROM ...>> — You MUST write << BEFORE any SQL keyword. The << must appear in the output before SELECT. Example: SQL: <<SELECT age, hometown FROM teacher>>. Select ONLY the exact columns the question asks for. Do not write SELECT before <<.");

var steps: nat := 0;

// Phase 1: Up to 10 unconstrained steps, watching for natural "<<" emission.
// With the guidance instructing the model to emit << before SELECT, the model
// should naturally generate "SQL", ":", " ", "<<" within 4-5 steps, making the
// << visible to the evaluator and enabling final_answer_span extraction.
while steps < maxSteps && steps < 10 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if the model did not emit it naturally within the preamble.
// This path produces an invisible (structural) <<, but the constrained SQL that
// follows will still be syntactically correct.
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3+4: Generate full SQL query and close constrained span.
// CloseSpanWithinBudget tracks the LONGEST complete prefix, ensuring WHERE/JOIN/
// GROUP BY/ORDER BY clauses are included (not stopped at first complete parse).
// Budget=400 covers all Spider query lengths (median ~23 tokens, max ~249).
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 400 {
    closeBudget := remaining;
  } else {
    closeBudget := 400;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

